const b = $json.body ?? $json;
const severity = (b.severity ?? "info").toString().toLowerCase();
const source = (b.source ?? "unknown").toString();
const message = (b.message ?? "").toString();
const timestamp = (b.timestamp ?? $now.toISO()).toString();
const label = severity.toUpperCase();
const payload = {
  text: "[" + label + "] hrmny ops alert from " + source + ": " + message,
  cardsV2: [{
    cardId: "hrmny-ops-alert",
    card: {
      header: { title: "hrmny Ops Alert", subtitle: label + " - " + source },
      sections: [{ widgets: [
        { decoratedText: { topLabel: "Severity", text: label } },
        { decoratedText: { topLabel: "Source", text: source } },
        { decoratedText: { topLabel: "Message", text: message, wrapText: true } },
        { decoratedText: { topLabel: "Timestamp", text: timestamp } }
      ] }]
    }
  }]
};
return { json: { severity: severity, source: source, message: message, timestamp: timestamp, payload: payload } };
